-- Release 6 data: the page content that lived in content/workshops/*.json moves onto
-- the database rows, so the pages render from here. Generated from those files,
-- word for word. Safe to re-run: it fills only what is still empty.

insert into public.workshop_series (slug, name, presenter, positioning, intro, standalone, disclaimer)
values ($seed$get-paid-for-automation$seed$, $seed$Get Paid for Automation$seed$, $seed$Bulletproof Automations$seed$, $seed$You know how to automate. Now learn how to turn those skills into paying work.$seed$, $seed$["Plenty of people can build a workflow. Far fewer can find a business that needs one, price the work, win the contract and deliver it well enough to be hired again. Tutorials and certifications cover the first part. This series covers the rest.","It is for people who already build automations, in n8n, Make, Zapier, Microsoft Power Automate and Power Apps, custom integrations or AI-powered tools. The platform does not matter here. What matters is turning the skill into work someone will pay for.","The first workshop is about pricing: what to charge, and how to explain it. The nine that follow cover the rest of the process, from choosing who to sell to and finding clients to writing proposals, closing deals, delivering and winning work abroad."]$seed$::jsonb, $seed$Each workshop stands alone. You do not need to take the whole series, or take the workshops in order.$seed$, $seed$Get Paid for Automation is organized and presented solely by Bulletproof Automations, an independent training provider. n8n, Make, Zapier, Microsoft Power Automate and Power Apps are named only to describe the tools participants use; none of their owners sponsors, endorses or is affiliated with this series. The workshops teach business skills and do not guarantee clients, contracts or income.$seed$)
on conflict (slug) do nothing;

-- Workshop 01 (live): content and series place only. Price, date, places and
-- every booking field are left exactly as they are.
update public.workshop_sessions set content = $seed${"summary":"Stop guessing what your automation work is worth. In three hours you learn to cost a project, choose a pricing approach and write a quotation you can explain to a client, then price a realistic project yourself.","directory_line":"Cost a project, choose a pricing approach and write a quotation you can explain to a client.","description":"A live 3-hour workshop for automation practitioners: cost a project, choose a pricing approach and write a quote you can defend. Saturday 12 December, GHS 350.","audience":"Automation practitioners who want to price paid work with confidence","why":["You can build automations and deliver projects. Then a client asks how much the work will cost, and the number you give is a guess.","Guess low and you work for less than it costs you to deliver, especially once discovery, testing, revisions and support are counted. Guess high without a reason, and the client compares you with someone cheaper and stops replying.","This workshop replaces the guess with a method. You work out what a project costs you to deliver, what the problem is worth to the client and which pricing approach fits, so the price you quote is one you can explain and defend."],"outcomes":["Identify the business problem an automation project solves.","Estimate your actual costs of delivering the work.","Compare hourly, fixed-project and value-informed pricing.","Recognize common underpricing and overpricing mistakes.","Account for discovery, testing, revisions, support and project risk.","Develop a defensible quotation for an automation project.","Explain your proposed price to a prospective client."],"leave_with":["A pricing worksheet for Excel or Google Sheets that works out your real cost of delivery, a cost-based price, a fixed-project price with risk included, and a check against the value to the client.","A project quotation template with the problem, deliverables, exclusions, assumptions, fees, payment terms and change requests already laid out.","One realistic automation project, priced by you in the clinic, with the reasoning to back the number.","The pricing mistakes that cost automation practitioners the most, and how to avoid each one."],"run_of_show":[{"at":"0:00","title":"Why automation work is hard to price","detail":"Introduction, and the pricing problems participants bring with them"},{"at":"0:15","title":"What a project costs you, and what it is worth to the client","detail":"Your real hourly cost, delivery effort, tools, and the cost of the client's problem"},{"at":"1:00","title":"Choosing an approach and building the quote","detail":"Hourly, fixed-project and value-informed pricing; discovery, testing, revisions, support and risk; protecting your margin"},{"at":"1:45","title":"Break","detail":"15 minutes"},{"at":"2:00","title":"Project pricing clinic","detail":"Price a realistic automation project yourself, explain your number, then questions"}],"good_fit":"You can already build and deliver automations, in n8n, Make, Zapier, Microsoft Power Automate or Power Apps, or with code. You have quoted a project and felt unsure of the number, or put off quoting because you did not know where to start. Freelancers, independent consultants, small automation service providers and technical professionals looking for paying clients all fit.","not_fit":"You have not built a working automation yet. This is not an introductory building class, so start there first. It is also not a certification: the workshop is training only. And if you want a promise of clients or income, no honest workshop can make one.","bring":"a laptop with Excel or Google Sheets and, if you have one, a project you have recently quoted or are about to quote.","faq":[{"q":"Am I technically ready for this?","a":"If you have built and delivered at least one working automation, on any platform, yes. The workshop does not teach building. It assumes you can already do the work and teaches you to price it."},{"q":"Does it matter which automation platform I use?","a":"No. The examples draw on n8n, Make, Zapier, Microsoft Power Automate and Power Apps, custom integrations and AI automation, but pricing works the same way whichever tool does the work."},{"q":"Are the examples relevant to Ghana?","a":"Yes. The worked examples and the clinic project come from the kind of work Ghanaian small businesses and service providers commission, priced in cedis, alongside an international freelance example priced in US dollars."},{"q":"Is this a certification?","a":"No. It is a training workshop. It does not award, and does not count towards, any Bulletproof Automations certification."},{"q":"Do I have to take the whole series?","a":"No. Each workshop in Get Paid for Automation stands alone. Take the ones you need, in any order."},{"q":"How do I pay?","a":"Register on this page, then pay GHS 350 on Paystack's secure checkout by mobile money or card. Your place is confirmed when Paystack confirms the payment, and your confirmation email follows."},{"q":"Is there a lower price?","a":"Three ways, and they never combine. With an Intermediate graduate's referral code or link you pay GHS 300. Holders of a valid Bulletproof Automation Foundations Certificate pay GHS 280. Intermediate graduates with a valid issued certificate, whose training fees are fully paid, attend free in one of five places reserved for them. If more than one applies, you get the lowest price. A certificate price needs a one-time code, which we email to the address on your certificate, and it is yours alone: it cannot be passed to someone else."},{"q":"How do I join?","a":"Live on Google Meet, by invitation. When you register, give us the Google account you will join with. Once Paystack confirms your payment, we add that account to the workshop's Google Calendar invitation, and Google emails it the Meet link. Only invited accounts can get in, so join signed in to that account, from a laptop if you can."},{"q":"Will this make me money?","a":"It will help you price work accurately and explain your price with confidence. It cannot guarantee clients, contracts or income. Those depend on your market, your skills and your effort."}],"instructor":"johnathan"}$seed$::jsonb,
  series_slug = $seed$get-paid-for-automation$seed$, series_number = 1
 where slug = $seed$what-to-charge-for-automation$seed$ and content = '{}'::jsonb;

-- Workshops 02 to 10: planned. Drafts with no date, announced as coming soon,
-- carrying the standard workshop terms so opening one needs only a date and
-- its Calendar event.
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
  content, series_slug, series_number, announce, admin_notes)
values ($seed$who-should-you-sell-to$seed$, 'workshop', $seed$Who should you sell to?$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Find the businesses that need your skills and can pay for them.","problem":"Many automation freelancers try to sell to everyone. They end up pitching businesses with no budget, no clear problem, or a problem nobody can automate well. A clear ideal client profile tells you where to spend your time, and where not to.","audience":"Practitioners who can deliver automation work but are unsure which businesses to approach first.","outcomes":["Describe your ideal client by industry, size, processes and budget.","Spot the signs that a business has a costly, repetitive problem worth automating.","Judge whether a prospect can realistically pay for the work.","Match prospects to the problems you can already solve well.","Write a short statement of who you serve and what you fix."],"series_fit":"Workshop 01 helps you price the work. This one decides whose work to price. A clear client profile makes every later step, from finding clients to writing proposals, more focused."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 2, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
  content, series_slug, series_number, announce, admin_notes)
values ($seed$where-are-the-clients$seed$, 'workshop', $seed$Where are the clients?$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Practical ways to find and approach businesses that need automation.","problem":"Knowing who you want to serve is not the same as meeting them. Most practitioners rely on luck and the occasional referral. A repeatable way to find prospects and open a conversation is what turns a skill into a steady flow of work.","audience":"Practitioners who know what they offer but have few prospective clients.","outcomes":["Find prospects among local businesses, professional networks and industry associations.","Ask for, and earn, referrals without awkwardness.","Use online communities and freelance platforms without competing on price alone.","Write a first message that gets a reply rather than being ignored.","Keep a simple record of who you have contacted and what happens next."],"series_fit":"Builds on the client profile from Workshop 02 and leads into Workshop 04, where the first conversation becomes a discovery session."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 3, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
