values ($seed$discover-what-clients-need$seed$, 'workshop', $seed$Discover what clients need$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Ask the questions that reveal problems worth paying to solve.","problem":"Clients rarely ask for an automation. They describe a frustration: invoices chased by hand, orders typed in twice, a report that takes a day. Discovery turns that frustration into a defined problem with a cost attached, and that is what makes a project worth paying for.","audience":"Practitioners who get to the first meeting but leave without a clear project.","outcomes":["Run a structured discovery conversation.","Map how a business process works today, including the workarounds.","Estimate what the current problem costs in time, errors and missed revenue.","Separate real automation opportunities from problems that need a different fix.","Summarize your findings so the client agrees on what needs solving."],"series_fit":"Discovery supplies the facts that the scope in Workshop 05 and the price in Workshop 01 depend on."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 4, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
