values ($seed$scope-it-before-you-quote-it$seed$, 'workshop', $seed$Scope it before you quote it$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Agree what you are building before you agree what it costs.","problem":"Most project disputes start with a vague scope. The client expected one thing, the builder delivered another, and the extra work went unpaid. A clear scope protects both sides before any money changes hands.","audience":"Practitioners who have had projects grow beyond what they quoted.","outcomes":["Define deliverables and requirements in plain language.","Write assumptions and exclusions so the limits are agreed in advance.","Set acceptance criteria that say when the work is finished.","Handle change requests with a simple, fair process.","Turn a scope into the basis for an accurate quote."],"series_fit":"Connects discovery in Workshop 04 to pricing in Workshop 01 and to the proposal in Workshop 06."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 5, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
