values ($seed$close-the-deal$seed$, 'workshop', $seed$Close the deal$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Move from an interested client to a signed agreement.","problem":"Plenty of proposals stall. The client asks for a discount, compares you with someone cheaper, or simply stops replying. Knowing how to discuss fees, answer objections and follow up is often the difference between a busy month and an empty one.","audience":"Practitioners whose proposals get interest but not agreement.","outcomes":["Discuss your fee calmly and explain what it covers.","Respond to common objections about price, timing and trust.","Negotiate reasonable terms without cutting your price by reflex.","Follow up on a proposal without pestering.","Confirm the agreement in writing before any work starts."],"series_fit":"Follows Workshop 06. Once the proposal is sent, this is how it becomes a contract."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 7, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
