values ($seed$deliver-like-a-professional$seed$, 'workshop', $seed$Deliver like a professional$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Run projects so clients come back and refer you.","problem":"Winning the project is half the job. Missed updates, untested workflows and handovers nobody understands cost practitioners their reputation, and reputation is where referrals come from.","audience":"Practitioners who are starting to deliver paid projects and want them to run smoothly.","outcomes":["Set expectations at the start about communication, timing and the client's responsibilities.","Report progress so the client is never surprised.","Test deliverables against the agreed acceptance criteria.","Hand over with documentation the client can actually use.","Ask for feedback, testimonials and referrals at the right moment."],"series_fit":"Delivers on the scope and proposal from Workshops 05 and 06, and sets up the ongoing relationship covered in Workshop 09."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 8, true, 'Imported from content/workshops/series as a planned workshop')
on conflict (slug) do nothing;
insert into public.workshop_sessions (slug, kind, title, starts_at, duration_minutes, format, price_ghs, capacity, status,
  admission, reserved_graduate_seats, foundations_discount_pct, graduate_free, referral_discount_ghs, referral_commission_ghs,
