values ($seed$win-international-clients$seed$, 'workshop', $seed$Win international clients$seed$, null, 180, 'live online', 350, 25, 'draft', 'invite', 5, 20, true, 50, 50,
  $seed${"summary":"Offer your automation services to clients outside Ghana.","problem":"Automation work can be delivered from anywhere, and many overseas businesses hire remote specialists. Competing for that work means presenting your services for a different market, quoting in another currency, and handling contracts, payments and time zones across borders.","audience":"Practitioners ready to take on clients outside Ghana, or already doing so informally.","outcomes":["Position your services for overseas buyers.","Communicate professionally across cultures and time zones.","Prepare international quotations, including currency and payment terms.","Understand the practical points of cross-border contracts and getting paid.","Decide which international opportunities fit your capacity."],"series_fit":"Applies the whole series, from pricing to delivery, to clients in other markets."}$seed$::jsonb, $seed$get-paid-for-automation$seed$, 10, true, 'Imported from content/workshops/series as a planned workshop')
